def encode_runs(text):
    result = ""
    count = 1

    for i in range(1, len(text)):
        if text[i] == text[i-1]:
            count += 1
        else:
            if count > 1:
                result += f"{count}{text[i-1]}"
            else:
                result += text[i-1]
            count = 1

    # Handle the last run
    if count > 1:
        result += f"{count}{text[-1]}"
    else:
        result += text[-1]

    return result
