def encode_runs(text):
    result = []
    count = 1
    prev_char = text[0]

    for char in text[1:]:
        if char == prev_char:
            count += 1
        else:
            if count > 1:
                result.append(f"{count}{prev_char}")
            else:
                result.append(prev_char)
            prev_char = char
            count = 1

    if count > 1:
        result.append(f"{count}{prev_char}")
    else:
        result.append(prev_char)

    return ''.join(result)
