def tag_message(priority, message):
    # Clamp the priority to the valid range (0-9)
    if priority < 0:
        priority = 0
    elif priority > 9:
        priority = 9

    # Return the tagged message based on the priority
    if priority == 0:
        return f"Urgent: {message}"
    elif priority == 1:
        return f"Important: {message}"
    elif priority == 2:
        return f"Normal: {message}"
    elif priority == 3:
        return f"Low: {message}"
    elif priority == 4:
        return f"Emergency: {message}"
    elif priority == 5:
        return f"Critical: {message}"
    elif priority == 6:
        return f"Warning: {message}"
    elif priority == 7:
        return f"Notice: {message}"
    elif priority == 8:
        return f"Information: {message}"
